def remember_existing_authors(apps, schema_editor):
    """Messages and homework written before this change: save who wrote them now, so the name is
    still there if that person is removed later."""
    ChatMessage = apps.get_model('core', 'ChatMessage')
    Homework = apps.get_model('core', 'Homework')
    Teacher = apps.get_model('core', 'Teacher')
    Manager = apps.get_model('core', 'Manager')

    teacher_user_ids = set(Teacher.objects.values_list('user_id', flat=True))
    manager_user_ids = set(Manager.objects.values_list('user_id', flat=True))

    def name_of(user):
        return (f'{user.first_name} {user.last_name}'.strip() or user.username)[:150]

    for message in ChatMessage.objects.filter(sender__isnull=False).select_related('sender').iterator():
        user = message.sender
        role = ('admin' if user.is_superuser else 'manager' if user.id in manager_user_ids
                else 'teacher' if user.id in teacher_user_ids else 'student')
        ChatMessage.objects.filter(pk=message.pk).update(sender_name=name_of(user), sender_role=role)

    for homework in Homework.objects.filter(created_by__isnull=False).select_related('created_by__user').iterator():
        Homework.objects.filter(pk=homework.pk).update(created_by_name=name_of(homework.created_by.user))


